entries[45731] = { ["name"] = "Glyph of Tranquilizing Shot", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Tranquilizing Shot no longer costs Focus, but has a 10 sec cooldown.\nSell Price:" }
entries[45732] = { ["name"] = "Glyph of Aspect of the Cheetah", ["text"] = "Minor Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Aspect of the Cheetah no longer causes you to be dazed when struck. Instead, the effect is cancelled and all your Aspects are placed on a 4 sec cooldown.\nSell Price:" }
entries[45733] = { ["name"] = "Glyph of Master's Call", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the duration of your Master's Call by 4 sec.\nSell Price:" }
entries[45734] = { ["name"] = "Glyph of Scatter Shot", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the range of Scatter Shot by 3 yards.\nSell Price:" }
entries[45735] = { ["name"] = "Glyph of Mirrored Blades", ["text"] = "Major Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen attacked by a spell while in Deterrence, you have a 100% chance to reflect it back at the attacker.\nSell Price:" }
entries[45736] = { ["name"] = "Glyph of Water Elemental", ["text"] = "Major Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the health of your Water Elemental by 40%, and allows it to cast while moving. When in Assist mode and in combat, commanding your Water Elemental to Follow will cause it to stay near you and autocast Waterbolt when your target is in range.\nSell Price:" }
entries[45737] = { ["name"] = "Glyph of Slow", ["text"] = "Major Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Arcane Blast spell applies the Slow spell to any target it damages if no target is currently affected by your Slow.\nSell Price:" }
entries[45738] = { ["name"] = "Glyph of Illusion", ["text"] = "Minor Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nTeaches you the ability Illusion.\n\nTransforms the Mage to look like someone else for 2 min.\nSell Price:" }
entries[45739] = { ["name"] = "Glyph of Mirror Image", ["text"] = "Minor Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Mirror Images cast Arcane Blast or Fireball instead of Frostbolt depending on your primary talent tree.\nSell Price:" }
entries[45740] = { ["name"] = "Glyph of Deep Freeze", ["text"] = "Major Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Deep Freeze spell is no longer on the global cooldown, but its duration is reduced by 1 sec.\nSell Price:" }
entries[45741] = { ["name"] = "Glyph of Beacon of Light", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nRemoves the global cooldown on Beacon of Light.\nSell Price:" }
entries[45742] = { ["name"] = "Glyph of Hammer of the Righteous", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nThe physical damage reduction caused by Hammer of the Righteous now lasts 50% longer.\nSell Price:" }
entries[45743] = { ["name"] = "Glyph of Divine Storm", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Divine Storm also heals you for 5% of your maximum health.\nSell Price:" }
entries[45744] = { ["name"] = "Glyph of the Alabaster Shield", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour successful blocks increase the damage of your next Shield of the Righteous by 10%. Stacks up to 3 times.\nSell Price:" }
entries[45745] = { ["name"] = "Glyph of Divine Plea", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nDivine Plea returns 50% less mana but has a 50% shorter cooldown.\nSell Price:" }
entries[45746] = { ["name"] = "Glyph of Holy Shock", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nDecreases the healing of Holy Shock by 50% but increases its damage by 50%.\nSell Price:" }
entries[45747] = { ["name"] = "Glyph of Inquisition", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen you land a killing blow on an opponent that yields experience or honor, the duration of your Inquisition is increased by 30 sec.\nSell Price:" }
entries[45753] = { ["name"] = "Glyph of Dispersion", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown on Dispersion by 15 sec.\nSell Price:" }
entries[45755] = { ["name"] = "Glyph of Leap of Faith", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Leap of Faith spell now also clears all movement impairing effects from your target.\nSell Price:" }
entries[45756] = { ["name"] = "Glyph of Penance", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the mana cost of Penance by 20% but allows Penance to be cast while moving.\nSell Price:" }
entries[45757] = { ["name"] = "Glyph of Focused Mending", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nCauses your Prayer of Mending to only bounce between the target and the caster.\nSell Price:" }
entries[45758] = { ["name"] = "Glyph of Mind Spike", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour successful non-instant Mind Spikes, reduce the cast time of your next Mind Blast within 9 sec by 50%. This effect can stack up to 2 times.\nSell Price:" }
entries[45760] = { ["name"] = "Glyph of Binding Heal", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Binding Heal spell now heals a third friendly target within 20 yards, but costs 35% more mana.\nSell Price:" }
